cssRules:
.editorial-header {
  border-bottom: 2px solid currentColor;
  padding-bottom: 8px;
  margin-bottom: 20px;
}
.editorial-meta {
  display: flex;
  justify-content: space-between;
  font-family: monospace;
  font-size: 11px;
  letter-spacing: 0.1em;
  opacity: 0.7;
}
.editorial-title {
  font-size: 24px;
  font-weight: 800;
  margin-top: 4px;
  letter-spacing: -0.02em;
}
